{"command":"cat << 'EOF' > main.go
package main

import (
	"bufio"
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
)

var (
	buildRe    = regexp.MustCompile(`^#\s+(.*)$`)
	startRe    = regexp.MustCompile(`^===\s+RUN\s+(Test)?(.*)$`)
	passRe     = regexp.MustCompile(`^---\s+PASS:\s+(Test)?(.*?)\s*(?:\(([0-9.]+s)\))?\s*$`)
	failRe     = regexp.MustCompile(`^---\s+FAIL:\s+(Test)?(.*?)\s*(?:\(([0-9.]+s)\))?\s*$`)
	skipRe     = regexp.MustCompile(`^---\s+SKIP:\s+(Test)?(.*?)\s*(?:\(([0-9.]+s)\))?\s*$`)
	passPkgRe  = regexp.MustCompile(`^PASS\s*$`)
	failPkgRe  = regexp.MustCompile(`^FAIL\s*$`)
	okRe       = regexp.MustCompile(`(?m)^ok\s+(.*?)\s*(?:([0-9.]+s|\(cached\))\s*)?$`)
	failPkgLine= regexp.MustCompile(`(?m)^FAIL(.*?(?:[0-9.]+s|\(cached\)))\s*$`)
	skipPkgRe  = regexp.MustCompile(`^\?\s+(.*?(?:\[no test files\]))\s*$`)
	coverRe    = regexp.MustCompile(`^coverage:\s+([0-9.]+)%\s+of statements$`)

	fileLineRe = regexp.MustCompile(`([^\s]+\.go)(:[0-9]+(?:[0-9:]*)?)`)
)

type Style struct {
	bold, faint, italic, underline, blinkSlow, blinkRapid, inverse, conceal, crossOut, frame, encircle, overline bool
	foreground, background string
	hide bool
}

func (s Style) String() string {
	if !colorEnabled { return "" }
	var codes []int
	if s.foreground != "" { codes = append(codes, colorCode(s.foreground, false)) }
	if s.background != "" { codes = append(codes, colorCode(s.background, true)) }
	if s.bold { codes = append(codes, 1) }

	if len(codes) == 0 { return "" }
	res := ""
	for _, c := range codes {
		res += fmt.Sprintf("\033[%dm", c)
	}
	return res
}

func colorCode(name string, bg bool) int {
	base := 30
	if bg { base = 40 }
	switch name {
	case "black": return base
	case "red": return base + 1
	case "green": return base + 2
	case "yellow": return base + 3
	case "blue": return base + 4
	case "magenta": return base + 5
	case "cyan": return base + 6
	case "white": return base + 7
	case "lightBlack": return base + 60
	case "lightRed": return base + 61
	case "lightGreen": return base + 62
	case "lightYellow": return base + 63
	case "lightBlue": return base + 64
	case "lightMagenta": return base + 65
	case "lightCyan": return base + 66
	case "lightWhite": return base + 67
	}
	return base + 9
}

var (
	labelType = "long"
	coverThreshold = 50.0
	leaveTestPrefix = false

	buildStyle    = Style{bold: true, foreground: "yellow"}
	startStyle    = Style{foreground: "lightBlack"}
	passStyle     = Style{foreground: "green"}
	failStyle     = Style{bold: true, foreground: "red"}
	skipStyle     = Style{foreground: "lightBlack"}
	passPkgStyle  = Style{foreground: "green", hide: true}
	failPkgStyle  = Style{bold: true, foreground: "red", hide: true}
	coveredStyle  = Style{foreground: "green"}
	uncoveredStyle= Style{bold: true, foreground: "yellow"}
	fileStyle     = Style{foreground: "cyan"}
	lineStyle     = Style{foreground: "magenta"}

	colorEnabled = true
)

func getLabel(cat string) string {
	if labelType == "none" { return "     | " }
	if labelType == "short" {
		switch cat {
		case "BUILD": return "!!   | "
		case "START": return ">    | "
		case "PASS":  return "o    | "
		case "FAIL":  return "x    | "
		case "SKIP":  return "-    | "
		case "COVER": return "%    | "
		}
	}
	switch cat {
	case "BUILD": return "BUILD| "
	case "START": return "START| "
	case "PASS":  return "PASS | "
	case "FAIL":  return "FAIL | "
	case "SKIP":  return "SKIP | "
	case "COVER": return "COVER| "
	}
	return "     | "
}

func main() {
	if os.Getenv("RICHGO_FORCE_COLOR") != "1" {
		stat, _ := os.Stdout.Stat()
		if (stat.Mode() & os.ModeCharDevice) == 0 {
			colorEnabled = false
		}
	} else {
		colorEnabled = true
	}

	loadConfig(".richstyle.yaml")

	if len(os.Args) > 1 && os.Args[1] == "testfilter" {
		runFilter()
	} else {
		fmt.Println("richgo must be used with 'testfilter' or 'test'")
	}
}

func loadConfig(path string) {
	b, err := os.ReadFile(path)
	if err != nil { return }
	lines := strings.Split(string(b), "\n")
	section := ""
	for _, line := range lines {
		if match := regexp.MustCompile(`^([a-zA-Z]+):\s*(.*)$`).FindStringSubmatch(line); match != nil {
			key, val := match[1], match[2]
			if val == "" || val == "{" {
				section = key
			} else {
				setGlobal(key, val)
				section = ""
			}
		} else if match := regexp.MustCompile(`^\s+([a-zA-Z]+):\s*(.*)$`).FindStringSubmatch(line); match != nil {
			key, val := match[1], match[2]
			setSection(section, key, val)
		}
	}
}

func setGlobal(key, val string) {
	val = strings.Trim(val, " \r\n\"'")
	switch key {
	case "labelType": labelType = val
	case "leaveTestPrefix": leaveTestPrefix = (val == "true")
	case "coverThreshold": coverThreshold, _ = strconv.ParseFloat(val, 64)
	}
}

func setSection(sec, key, val string) {
	val = strings.Trim(val, " \r\n\"'")
	var s *Style
	switch sec {
	case "buildStyle": s = &buildStyle
	case "startStyle": s = &startStyle
	case "passStyle": s = &passStyle
	case "failStyle": s = &failStyle
	case "skipStyle": s = &skipStyle
	case "passPackageStyle": s = &passPkgStyle
	case "failPackageStyle": s = &failPkgStyle
	case "coveredStyle": s = &coveredStyle
	case "uncoveredStyle": s = &uncoveredStyle
	case "fileStyle": s = &fileStyle
	case "lineStyle": s = &lineStyle
	default: return
	}
	switch key {
	case "bold": s.bold = (val == "true")
	case "faint": s.faint = (val == "true")
	case "foreground": s.foreground = val
	case "background": s.background = val
	case "hide": s.hide = (val == "true")
	}
}

func runFilter() {
	scanner := bufio.NewScanner(os.Stdin)
	var lastStyleStr string

	reset := ""
	if colorEnabled { reset = "\033[0m" }

	for scanner.Scan() {
		line := scanner.Text()

		if match := buildRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = buildStyle.String()
			fmt.Printf("%s%s%s\n%s", lastStyleStr, getLabel("BUILD"), match[1], reset)
			continue
		}
		if match := startRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = startStyle.String()
			name := match[2]
			if leaveTestPrefix && match[1] == "Test" { name = "Test" + name }
			fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("START"), name, reset)
			continue
		}
		if match := passRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = passStyle.String()
			name := match[2]
			if leaveTestPrefix && match[1] == "Test" { name = "Test" + name }
			if match[3] != "" {
				fmt.Printf("%s%s%s (%s)%s\n", lastStyleStr, getLabel("PASS"), name, match[3], reset)
			} else {
				fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("PASS"), name, reset)
			}
			continue
		}
		if match := failRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = failStyle.String()
			name := match[2]
			if leaveTestPrefix && match[1] == "Test" { name = "Test" + name }
			if match[3] != "" {
				fmt.Printf("%s%s%s (%s)%s\n", lastStyleStr, getLabel("FAIL"), name, match[3], reset)
			} else {
				fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("FAIL"), name, reset)
			}
			continue
		}
		if match := skipRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = skipStyle.String()
			name := match[2]
			if leaveTestPrefix && match[1] == "Test" { name = "Test" + name }
			if match[3] != "" {
				fmt.Printf("%s%s%s (%s)%s\n", lastStyleStr, getLabel("SKIP"), name, match[3], reset)
			} else {
				fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("SKIP"), name, reset)
			}
			continue
		}

		if passPkgRe.MatchString(line) {
			if passPkgStyle.hide { continue }
			lastStyleStr = passPkgStyle.String()
			fmt.Printf("%sPASS%s\n", lastStyleStr, reset)
			continue
		}
		if failPkgRe.MatchString(line) {
			if failPkgStyle.hide { continue }
			lastStyleStr = failPkgStyle.String()
			fmt.Printf("%sFAIL%s\n", lastStyleStr, reset)
			continue
		}

		if match := okRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = passStyle.String()
			if match[2] != "" {
				fmt.Printf("%s%s%s %s\n", lastStyleStr, getLabel("PASS"), match[1], reset)
			} else {
				fmt.Printf("%s%s%s\n %s", lastStyleStr, getLabel("PASS"), match[1], reset)
			}
			continue
		}

		if match := failPkgLine.FindStringSubmatch(line); match != nil {
			lastStyleStr = failStyle.String()
			fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("FAIL"), match[1], reset)
			continue
		}

		if match := skipPkgRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = skipStyle.String()
			fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("SKIP"), match[1], reset)
			continue
		}

		if match := coverRe.FindStringSubmatch(line); match != nil {
			pct, _ := strconv.ParseFloat(match[1], 64)
			s := uncoveredStyle
			if pct >= coverThreshold { s = coveredStyle }
			lastStyleStr = s.String()

			hashes := int(pct / 10)
			if hashes > 10 { hashes = 10 }
			bar := strings.Repeat("#", hashes) + strings.Repeat("_", 10-hashes)

			fmt.Printf("%s%s%s%% [%s]%s\n", lastStyleStr, getLabel("COVER"), match[1], bar, reset)
			continue
		}

		// Default handler
		replaced := line
		if colorEnabled && strings.Contains(line, ".go:") {
			fs := fileStyle.String()
			ls := lineStyle.String()
			// Only colorize if formats match
			replaced = fileLineRe.ReplaceAllString(line, fs+"$1"+reset+ls+"$2"+reset+lastStyleStr)
		}

		if lastStyleStr != "" {
			fmt.Printf("%s     | %s%s\n", lastStyleStr, replaced, reset)
		} else {
			fmt.Printf("     | %s\n", replaced)
		}
	}
}
EOF
./compile.sh
"}

