	case "faint": s.faint = (val == "true")
	case "foreground": s.foreground = val
	case "background": s.background = val
	case "hide": s.hide = (val == "true")
	}
}

func runFilter(scanner *bufio.Scanner) {
	var lastStyleStr string

	reset := ""
	if colorEnabled { reset = "\033[0m" }

	for scanner.Scan() {
		line := scanner.Text()

		if match := buildRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = buildStyle.String()
			fmt.Printf("%s%s%s\n%s", lastStyleStr, getLabel("BUILD"), match[1], reset)
			continue
		}
		if match := startRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = startStyle.String()
			name := match[2]
			if !leaveTestPrefix && match[1] == "Test" { 
                // do nothing, Test is dropped 
            } else if match[1] == "Test" { 
                name = "Test" + name 
            }
			fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("START"), name, reset)
			continue
		}
		if match := passRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = passStyle.String()
			name := match[2]
			if !leaveTestPrefix && match[1] == "Test" { } else if match[1] == "Test" { name = "Test" + name }
			if match[3] != "" {
				fmt.Printf("%s%s%s (%s)%s\n", lastStyleStr, getLabel("PASS"), name, match[3], reset)
			} else {
				fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("PASS"), name, reset)
			}
			continue
		}
		if match := failRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = failStyle.String()
			name := match[2]
			if !leaveTestPrefix && match[1] == "Test" { } else if match[1] == "Test" { name = "Test" + name }
			if match[3] != "" {
				fmt.Printf("%s%s%s (%s)%s\n", lastStyleStr, getLabel("FAIL"), name, match[3], reset)
			} else {
				fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("FAIL"), name, reset)
			}
			continue
		}
		if match := skipRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = skipStyle.String()
			name := match[2]
			if !leaveTestPrefix && match[1] == "Test" { } else if match[1] == "Test" { name = "Test" + name }
			if match[3] != "" {
				fmt.Printf("%s%s%s (%s)%s\n", lastStyleStr, getLabel("SKIP"), name, match[3], reset)
			} else {
				fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("SKIP"), name, reset)
			}
			continue
		}

		if passPkgRe.MatchString(line) {
			if passPkgStyle.hide { continue }
			lastStyleStr = passPkgStyle.String()
			fmt.Printf("%sPASS%s\n", lastStyleStr, reset)
			continue
		}
		if failPkgRe.MatchString(line) {
			if failPkgStyle.hide { continue }
			lastStyleStr = failPkgStyle.String()
			fmt.Printf("%sFAIL%s\n", lastStyleStr, reset)
			continue
		}

		if match := okRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = passStyle.String()
			if match[2] != "" {
				fmt.Printf("%s%s%s %s\n", lastStyleStr, getLabel("PASS"), match[1], reset)
			} else {
				fmt.Printf("%s%s%s\n %s", lastStyleStr, getLabel("PASS"), match[1], reset)
			}
			continue
		}

		if match := failPkgLine.FindStringSubmatch(line); match != nil {
			lastStyleStr = failStyle.String()
			fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("FAIL"), match[1], reset)
			continue
		}

		if match := skipPkgRe.FindStringSubmatch(line); match != nil {
			lastStyleStr = skipStyle.String()
			fmt.Printf("%s%s%s%s\n", lastStyleStr, getLabel("SKIP"), match[1], reset)
			continue
		}

		if match := coverRe.FindStringSubmatch(line); match != nil {
			pct, _ := strconv.ParseFloat(match[1], 64)
			s := uncoveredStyle
			if pct >= coverThreshold { s = coveredStyle }
			lastStyleStr = s.String()

			hashes := int(pct / 10)
			if hashes > 10 { hashes = 10 }
			bar := strings.Repeat("#", hashes) + strings.Repeat("_", 10-hashes)

			fmt.Printf("%s%s%s%% [%s]%s\n", lastStyleStr, getLabel("COVER"), match[1], bar, reset)
			continue
		}

		// Default handler
		replaced := line
		if colorEnabled && strings.Contains(line, ".go:") {
			fs := fileStyle.String()
			ls := lineStyle.String()
			replaced = fileLineRe.ReplaceAllString(line, fs+"$1"+reset+ls+"$2"+reset+lastStyleStr)
		}

		if lastStyleStr != "" {
			fmt.Printf("%s     | %s%s\n", lastStyleStr, replaced, reset)
		} else {
			fmt.Printf("     | %s\n", replaced)
		}
	}
}
